    <tr><td style="padding:10px;border-bottom:1px solid #e2e8f0">Canone suolo pubblico</td><td style="padding:10px;border-bottom:1px solid #e2e8f0">300 - 2.000+ euro</td><td style="padding:10px;border-bottom:1px solid #e2e8f0">Dipende da Comune, metri e giorni</td></tr>
