    <tr><td style="padding:10px;border-bottom:1px solid #e2e8f0">Furgone, gasolio, assicurazione</td><td style="padding:10px;border-bottom:1px solid #e2e8f0">2.000 - 6.000 euro</td><td style="padding:10px;border-bottom:1px solid #e2e8f0">Aumenta se fai mercati lontani</td></tr>
    <tr style="background:#f8fafc"><td style="padding:10px;border-bottom:1px solid #e2e8f0">Attrezzatura e imprevisti</td><td style="padding:10px;border-bottom:1px solid #e2e8f0">500 - 2.500 euro</td><td style="padding:10px;border-bottom:1px solid #e2e8f0">Teli, rotture, vento, manutenzioni, sostituzioni</td></tr>
  </tbody>
